-- ===========================================================================
-- 0054_team_gallery_publisher — how the team-gallery service gets its keys
--
-- 0053 left two secrets to be put in Vault by hand. Nobody should handle
-- them, so this replaces both:
--
--   * The ACCESS SECRET (signs visitors' passes) is generated BY THE DATABASE
--     when this migration is applied: 32 random bytes that no person ever
--     sees or copies.
--   * The PUBLISHER is the photographer's own JerseySort. It makes its key
--     on his computer and registers only the key's SHA-256 FINGERPRINT,
--     during a one-time CONNECT WINDOW that applying this migration opens
--     (24 hours). The first registration closes the window. The key itself
--     never leaves his computer, and the fingerprint cannot be turned back
--     into it.
--
-- If anything other than his JerseySort registered first, his JerseySort is
-- refused ("connected to another computer") and says so; reset_publisher()
-- (run by the approval-gated workflow) clears it and opens a new window.
-- WRITTEN AND TESTED, NOT APPLIED to any project.
--
-- rollback:
--   drop function if exists gallery.reset_publisher(integer);
--   drop function if exists gallery.register_publisher(text);
--   drop function if exists gallery.service_settings();
--   drop table if exists gallery.settings;
-- ===========================================================================

create table if not exists gallery.settings (
  id                     boolean primary key default true check (id),
  access_secret          text not null
                         default encode(extensions.gen_random_bytes(32), 'base64'),
  publisher_key_sha256   text check (publisher_key_sha256 is null
                                     or publisher_key_sha256 ~ '^[0-9a-f]{64}$'),
  publisher_connected_at timestamptz,
  connect_until          timestamptz
);
alter table gallery.settings enable row level security;
alter table gallery.settings force row level security;
revoke all on gallery.settings from public, anon, authenticated;
grant select, update on gallery.settings to service_role;

insert into gallery.settings (id, connect_until)
values (true, now() + interval '24 hours')
on conflict (id) do nothing;

-- What the Edge Function needs to run: the pass-signing secret and the
-- publisher's fingerprint (null until JerseySort connects).
create or replace function gallery.service_settings()
returns table (access_secret text, publisher_key_sha256 text)
language sql stable set search_path = '' as $$
  select s.access_secret, s.publisher_key_sha256 from gallery.settings s where s.id
$$;

-- JerseySort registers its key's fingerprint. Answers:
--   'connected'  registered now, or this fingerprint already is the publisher
--   'taken'      another fingerprint is registered (another computer)
--   'closed'     no connect window is open
create or replace function gallery.register_publisher(p_sha256 text)
returns text language plpgsql set search_path = '' as $$
declare s gallery.settings;
begin
  if p_sha256 is null or p_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'a fingerprint is 64 hex characters' using errcode = '22023';
  end if;
  select * into s from gallery.settings where id for update;
  if s.publisher_key_sha256 = p_sha256 then
    return 'connected';
  elsif s.publisher_key_sha256 is not null then
    return 'taken';
  elsif s.connect_until is null or s.connect_until < now() then
    return 'closed';
  end if;
  update gallery.settings
     set publisher_key_sha256 = p_sha256, publisher_connected_at = now(), connect_until = null
   where id;
  return 'connected';
end $$;

-- Forget the registered publisher and open a new connect window. For the
-- approval-gated "reconnect JerseySort" workflow, never the Edge Function.
create or replace function gallery.reset_publisher(p_hours integer default 24)
returns void language plpgsql set search_path = '' as $$
begin
  if p_hours is null or p_hours < 1 or p_hours > 72 then
    raise exception 'a connect window is 1 to 72 hours' using errcode = '22023';
  end if;
  update gallery.settings
     set publisher_key_sha256 = null, publisher_connected_at = null,
         connect_until = now() + make_interval(hours => p_hours)
   where id;
end $$;

revoke all on function gallery.service_settings() from public, anon, authenticated;
revoke all on function gallery.register_publisher(text) from public, anon, authenticated;
revoke all on function gallery.reset_publisher(integer) from public, anon, authenticated, service_role;
grant execute on function gallery.service_settings() to service_role;
grant execute on function gallery.register_publisher(text) to service_role;
